/** 检查角色是否有 NSFW CG 数据 */
export function hasNsfwData(character) {
    return character in NSFW_CG_DATA;
}
/** 获取角色的 NSFW CG 数据 */
export function getNsfwData(character) {
    return NSFW_CG_DATA[character];
}
/** 检查当前是否满足 NSFW 触发条件（角色有CG数据 + 当前地点是触发地点）
 *  triggerLocation 支持 "parent/spot" 格式用于消歧义（如多个地点都有"主卧"）
 *  也支持简单字符串格式（如 "人工湖岸"），直接匹配 spot 或 parent
 */
export function canTriggerNsfw(character, parent, spot) {
    const data = NSFW_CG_DATA[character];
    if (!data)
        return false;
    const trigger = data.triggerLocation;
    // 支持 "parent/spot" 格式：需要 parent 和 spot 都匹配
    if (trigger.includes('/')) {
        const [tParent, tSpot] = trigger.split('/');
        return tParent === parent && tSpot === (spot || '');
    }
    // 简单格式：匹配 spot 或 parent
    const currentLocation = spot || parent;
    return trigger === currentLocation;
}
/** 获取角色的触发地点提示 */
export function getNsfwTriggerLocation(character) {
    return NSFW_CG_DATA[character]?.triggerLocation;
}
/**
 * 获取角色在某阶段的所有 CG 索引（基于 stage.label 前缀匹配）
 * - 开始 → [0]
 * - 脱衣服 → [1, 2]
 * - 插入 → [3, 4, 5, 6, 7, 8, 9]
 * - 高潮 → [10, 11, 12]
 * - 事后 → [13]
 */
export function getNsfwPhaseIndices(character, phase) {
    const data = NSFW_CG_DATA[character];
    if (!data)
        return [];
    return data.stages
        .map((s, i) => ({ label: s.label, index: i }))
        .filter(({ label }) => label.startsWith(phase))
        .map(({ index }) => index);
}
/**
 * 根据当前场景地点，查找哪个角色的 triggerLocation 匹配
 * 用于 [nsfw:开始] 时自动确定角色
 */
export function getCharacterByTriggerLocation(parent, spot) {
    for (const [name, data] of Object.entries(NSFW_CG_DATA)) {
        if (canTriggerNsfw(name, parent, spot))
            return name;
    }
    return null;
}
