/**
 * 文本速度 & Auto 等待时间共享设置
 *
 * 设计动机：
 * StoryView 需要读取打字机速度和 Auto 模式等待时间，
 * SettingsPanel 也需要控制这些值。通过 pub-sub store 共享。
 *
 * 使用方式：
 *   import { textSettings, useTextSettings } from '../audio/textSettings';
 *   textSettings.setTextSpeed(2);              // 写入速度
 *   const { textSpeed, autoWaitMultiplier } = useTextSettings();  // React 组件中订阅
 */
import { useSyncExternalStore } from 'react';
const STORAGE_KEY = 'rent-boyfriend-text-settings';
function loadSettings() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
            const parsed = JSON.parse(raw);
            return {
                textSpeed: typeof parsed.textSpeed === 'number' ? parsed.textSpeed : 2,
                autoWaitMultiplier: typeof parsed.autoWaitMultiplier === 'number' ? parsed.autoWaitMultiplier : 1,
            };
        }
    }
    catch {
        // ignore
    }
    return { textSpeed: 2, autoWaitMultiplier: 1 };
}
function saveSettings(settings) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
    }
    catch {
        // ignore
    }
}
// ── 速度级别 → 每字符延迟(ms) 映射 ──
const SPEED_DELAYS = {
    0: 0, // 瞬间
    1: 55, // 慢
    2: 28, // 普通
    3: 10, // 快
};
/** 获取指定速度级别的每字符延迟 */
export function getTextDelay(speed) {
    return SPEED_DELAYS[speed] ?? 28;
}
// ── Pub-Sub ──
const listeners = new Set();
let state = loadSettings();
function notify() {
    listeners.forEach(fn => fn());
}
export const textSettings = {
    getState: () => state,
    getTextSpeed: () => state.textSpeed,
    getAutoWaitMultiplier: () => state.autoWaitMultiplier,
    setTextSpeed: (speed) => {
        state = { ...state, textSpeed: Math.max(0, Math.min(3, speed)) };
        saveSettings(state);
        notify();
    },
    setAutoWaitMultiplier: (m) => {
        state = { ...state, autoWaitMultiplier: Math.max(0.5, Math.min(2, m)) };
        saveSettings(state);
        notify();
    },
    subscribe: (fn) => {
        listeners.add(fn);
        return () => { listeners.delete(fn); };
    },
};
// ── React Hook ──
export function useTextSettings() {
    return useSyncExternalStore(textSettings.subscribe, textSettings.getState);
}
